import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CNDaxUod.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md"}'),l={name:"features.md"};function o(s,e,n,h,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<details class="details custom-block"><summary>Table of Contents/Overview</summary><nav class="table-of-contents"><ul><li><a href="#general-info">General info</a></li><li><a href="#website-features">Website features</a><ul><li><a href="#keep-track-of-everything-sold-in-snailcraft">Keep track of everything sold in Snailcraft</a></li><li><a href="#world-shop-statistics">World &amp; shop statistics</a></li><li><a href="#item-library">Item library</a></li><li><a href="#search-by-material-list">Search by material list</a></li><li><a href="#report-listings-or-sellers">Report listings or sellers</a></li><li><a href="#view-the-roadmap">View the roadmap</a></li><li><a href="#marketplace">Marketplace</a></li><li><a href="#mapart-gallery">Mapart gallery</a></li><li><a href="#collections">Collections</a></li><li><a href="#public-profiles">Public profiles</a></li><li><a href="#rare-dle-coming-soon">Rare-dle (coming soon)</a></li><li><a href="#image-maker">Image maker</a></li><li><a href="#quality-of-life-upgrades">Quality-of-life upgrades</a></li></ul></li><li><a href="#mod-features">Mod features</a><ul><li><a href="#automatically-scans-all-shop-chests">Automatically scans all shop chests</a></li><li><a href="#in-game-item-library-and-listings-overview">In-game item library and listings overview</a></li><li><a href="#mapart-scanner">Mapart scanner</a></li><li><a href="#watchlist">Watchlist</a></li><li><a href="#report-from-the-game">Report from the game</a></li><li><a href="#sold-item-notifications">Sold item notifications</a></li><li><a href="#new-items-at-shop-notifications">New items at shop notifications</a></li><li><a href="#butterfly-garden-helper">Butterfly garden helper</a></li><li><a href="#quest-helper">Quest helper</a></li></ul></li></ul></nav></details><h2 id="general-info" tabindex="-1">General info <a class="header-anchor" href="#general-info" aria-label="Permalink to &quot;General info&quot;">​</a></h2><p>The Snailcraft Trading Post website and mod are a project made by maxolotled, with help of Zyski for many QOL features! It exists to make searching through Snailcraft shops much easier, and has grown to provide way more features, seen below.</p><h2 id="website-features" tabindex="-1">Website features <a class="header-anchor" href="#website-features" aria-label="Permalink to &quot;Website features&quot;">​</a></h2><h3 id="keep-track-of-everything-sold-in-snailcraft" tabindex="-1"><a href="https://sctp.nl/" target="_blank" rel="noreferrer">Keep track of everything sold in Snailcraft</a> <a class="header-anchor" href="#keep-track-of-everything-sold-in-snailcraft" aria-label="Permalink to &quot;[Keep track of everything sold in Snailcraft](https://sctp.nl/)&quot;">​</a></h3><p>On the homepage, use a ton of filters to search for any item you may need, in the 25000+ item catalog</p><h3 id="world-shop-statistics" tabindex="-1"><a href="https://sctp.nl/stats" target="_blank" rel="noreferrer">World &amp; shop statistics</a> <a class="header-anchor" href="#world-shop-statistics" aria-label="Permalink to &quot;[World &amp; shop statistics](https://sctp.nl/stats)&quot;">​</a></h3><p>Check the statistics per item or seller, and log in to see your own shop&#39;s stats with hints on what to restock, what to reprice, and where someone undercuts you.</p><h3 id="item-library" tabindex="-1"><a href="https://sctp.nl/items" target="_blank" rel="noreferrer">Item library</a> <a class="header-anchor" href="#item-library" aria-label="Permalink to &quot;[Item library](https://sctp.nl/items)&quot;">​</a></h3><p>Thanks to LadyMaledicte, we have a library of all vanilla and rare items!</p><h3 id="search-by-material-list" tabindex="-1"><a href="https://sctp.nl/list" target="_blank" rel="noreferrer">Search by material list</a> <a class="header-anchor" href="#search-by-material-list" aria-label="Permalink to &quot;[Search by material list](https://sctp.nl/list)&quot;">​</a></h3><p>Upload your Litematica material list, and get a list of shops to visit it, plus filter on price or efficiency</p><h3 id="report-listings-or-sellers" tabindex="-1"><a href="https://sctp.nl/report" target="_blank" rel="noreferrer">Report listings or sellers</a> <a class="header-anchor" href="#report-listings-or-sellers" aria-label="Permalink to &quot;[Report listings or sellers](https://sctp.nl/report)&quot;">​</a></h3><p>Report a listing or seller to have a SCTP moderator check it and take action. Not official SC!</p><h3 id="view-the-roadmap" tabindex="-1"><a href="https://sctp.nl/roadmap" target="_blank" rel="noreferrer">View the roadmap</a> <a class="header-anchor" href="#view-the-roadmap" aria-label="Permalink to &quot;[View the roadmap](https://sctp.nl/roadmap)&quot;">​</a></h3><p>View the roadmap and suggest new features or report bugs.</p><h3 id="marketplace" tabindex="-1"><a href="https://sctp.nl/marketplace" target="_blank" rel="noreferrer">Marketplace</a> <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;[Marketplace](https://sctp.nl/marketplace)&quot;">​</a></h3><p>Post looking-for and selling ads, take bids, and post or answer jobs.</p><h3 id="mapart-gallery" tabindex="-1"><a href="https://sctp.nl/mapart" target="_blank" rel="noreferrer">Mapart gallery</a> <a class="header-anchor" href="#mapart-gallery" aria-label="Permalink to &quot;[Mapart gallery](https://sctp.nl/mapart)&quot;">​</a></h3><p>Every mapart found around Snailcraft with its artist, where to buy it and an optional price. Search by image, report mistakes, see collabs (the head artist first) and commissions (built by / commissioned by), and artists can claim, edit and upload their own pieces.</p><h3 id="collections" tabindex="-1"><a href="https://sctp.nl/collection" target="_blank" rel="noreferrer">Collections</a> <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;[Collections](https://sctp.nl/collection)&quot;">​</a></h3><p>Tick off the rare items and mapart you own, per world, and see how far along you are. Collections are public by default (you can hide yours), and you can make a shareable picture of what you still need or what you own.</p><h3 id="public-profiles" tabindex="-1">Public profiles <a class="header-anchor" href="#public-profiles" aria-label="Permalink to &quot;Public profiles&quot;">​</a></h3><p>Every player has a profile at sctp.nl/s/ff/yourname with their shop, mapart (with commission info), collection and marketplace history in one place.</p><h3 id="rare-dle-coming-soon" tabindex="-1">Rare-dle (coming soon) <a class="header-anchor" href="#rare-dle-coming-soon" aria-label="Permalink to &quot;Rare-dle (coming soon)&quot;">​</a></h3><p>A daily &quot;guess the secret rare&quot; game with points, streaks and leaderboards.</p><h3 id="image-maker" tabindex="-1">Image maker <a class="header-anchor" href="#image-maker" aria-label="Permalink to &quot;Image maker&quot;">​</a></h3><p>Make shareable pictures for Discord, X, Instagram, YouTube and more — 13 sizes and 12 styles — for mapart, rare items, collections, profiles and Rare-dle results.</p><h3 id="quality-of-life-upgrades" tabindex="-1">Quality-of-life upgrades <a class="header-anchor" href="#quality-of-life-upgrades" aria-label="Permalink to &quot;Quality-of-life upgrades&quot;">​</a></h3><p>Hide any table column and bring it back from the Columns menu, filter and sort by price per single item in diamond-equivalent (or turn conversion off), &quot;did you mean…?&quot; suggestions, and a general price check on every rare item.</p><h2 id="mod-features" tabindex="-1">Mod features <a class="header-anchor" href="#mod-features" aria-label="Permalink to &quot;Mod features&quot;">​</a></h2><h3 id="automatically-scans-all-shop-chests" tabindex="-1">Automatically scans all shop chests <a class="header-anchor" href="#automatically-scans-all-shop-chests" aria-label="Permalink to &quot;Automatically scans all shop chests&quot;">​</a></h3><p>The mod automatically scans all shop chests within reach, takes the price, seller, and content, and uploads it to the trading post website. Scanned chests are marked, and won&#39;t be scanned again for a configurable amount of minutes.</p><h3 id="in-game-item-library-and-listings-overview" tabindex="-1">In-game item library and listings overview <a class="header-anchor" href="#in-game-item-library-and-listings-overview" aria-label="Permalink to &quot;In-game item library and listings overview&quot;">​</a></h3><p>Most data from the website, like the item library and current listings, can be easily found and searched through in-game via the X-menu!</p><h3 id="mapart-scanner" tabindex="-1">Mapart scanner <a class="header-anchor" href="#mapart-scanner" aria-label="Permalink to &quot;Mapart scanner&quot;">​</a></h3><p>The mod finds item-frame mapart near you, stitches multi-map pieces together and uploads them to the mapart gallery in the background — without freezing your game or spamming chat. Turn it on or off, and see what it found, from the Mapart Scanner button on the X-menu.</p><h3 id="watchlist" tabindex="-1">Watchlist <a class="header-anchor" href="#watchlist" aria-label="Permalink to &quot;Watchlist&quot;">​</a></h3><p>The mod allows you to keep a watchlist for rares, as well as set a max price, and will notify you in-game if the item is found on the SCTP! Marketplace listings are included, and there are quick price buttons when you set a limit.</p><h3 id="report-from-the-game" tabindex="-1">Report from the game <a class="header-anchor" href="#report-from-the-game" aria-label="Permalink to &quot;Report from the game&quot;">​</a></h3><p>Spot a wrong listing? Hit the red [Report] button in a watchlist alert or the listings screen to send it to the moderators in one click.</p><h3 id="sold-item-notifications" tabindex="-1">Sold item notifications <a class="header-anchor" href="#sold-item-notifications" aria-label="Permalink to &quot;Sold item notifications&quot;">​</a></h3><p>The mod will alert you if it finds any items sold inside of your own shop when you walk through!</p><h3 id="new-items-at-shop-notifications" tabindex="-1">New items at shop notifications <a class="header-anchor" href="#new-items-at-shop-notifications" aria-label="Permalink to &quot;New items at shop notifications&quot;">​</a></h3><p>The mod automatically checks any shop you walk into for new items, and will notify you in chat if any new items are available. You can configure this to only notify you for rares as well!</p><h3 id="butterfly-garden-helper" tabindex="-1">Butterfly garden helper <a class="header-anchor" href="#butterfly-garden-helper" aria-label="Permalink to &quot;Butterfly garden helper&quot;">​</a></h3><p>Keep track of and automatically sell the butterflies in the butterfly garden! Credits for this feature go to Zyski 😄</p><h3 id="quest-helper" tabindex="-1">Quest helper <a class="header-anchor" href="#quest-helper" aria-label="Permalink to &quot;Quest helper&quot;">​</a></h3><p>Made by Zyski as well, there&#39;s a feature to show your current quest without needing to check your inventory every time!</p>',49)])])}const f=a(l,[["render",o]]);export{m as __pageData,f as default};
